def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opps = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)

    if not alive_opps:
        if hp <= 2 or no_water >= 1:
            return max(0.0, min(budget, 60.0))
        return max(0.0, min(budget, 18.0))

    prev_bids = []
    max_prev_bid = 0.0
    eric_like_pressure = 0.0
    richest_opp_budget = 0.0
    urgent_opp_count = 0

    for opp in alive_opps:
        obudget = opp.get('budget', 0.0)
        if obudget > richest_opp_budget:
            richest_opp_budget = obudget
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            urgent_opp_count += 1
        prev = opp.get('previous_trace', {})
        if prev:
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(bid)
                if bid > max_prev_bid:
                    max_prev_bid = bid
                if bid > eric_like_pressure:
                    eric_like_pressure = bid

    contested = len(alive_opps) >= 1
    low_supply = supply <= 18
    high_supply = supply >= 22

    if hp <= 1:
        return max(0.0, min(budget, 120.0))
    if no_water >= 2:
        return max(0.0, min(budget, 130.0))
    if hp <= 2 and no_water >= 1:
        return max(0.0, min(budget, 115.0))

    if prev_bids:
        if max_prev_bid >= 95.0:
            if hp >= 5 and no_water == 0:
                if high_supply:
                    return max(0.0, min(budget, 8.0))
                return max(0.0, min(budget, 5.0))
            if hp >= 3 and no_water == 0:
                return max(0.0, min(budget, 28.0))
            return max(0.0, min(budget, 108.0))

        if max_prev_bid >= 75.0:
            if hp >= 5 and no_water == 0:
                return max(0.0, min(budget, 18.0))
            if hp >= 3:
                return max(0.0, min(budget, max_prev_bid + 3.0))
            return max(0.0, min(budget, 92.0))

        target = max(42.0, max_prev_bid + 2.5)
        if low_supply:
            target += 8.0
        if urgent_opp_count > 0:
            target += 6.0
        if high_supply:
            target -= 6.0
        return max(0.0, min(budget, target))

    if hp <= 2 or no_water >= 1:
        return max(0.0, min(budget, 85.0))
    if low_supply and contested:
        return max(0.0, min(budget, 40.0))
    if high_supply:
        return max(0.0, min(budget, 16.0))
    return max(0.0, min(budget, 24.0))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15
    supply = int(day_context['supply'])
    day = int(day_context['day'])
    hp = int(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opponents = {aid: o for aid, o in opponents_status.items() if o['alive']}
    num_alive = len(alive_opponents)

    # If no competitors, minimal bid
    if num_alive == 0:
        return min(budget, DAILY_SALARY * 0.4)

    # Analyze previous traces
    highest_prev_bid = 0
    for aid, opp in alive_opponents.items():
        prev = opp.get('previous_trace', {})
        if prev and 'bid' in prev and prev['bid'] is not None:
            if prev['bid'] > highest_prev_bid:
                highest_prev_bid = float(prev['bid'])

    # Decision based on HP and supply
    if hp > 3:
        base_bid = DAILY_SALARY * 0.6
    elif hp > 1:
        base_bid = DAILY_SALARY * 0.75
    else:
        base_bid = DAILY_SALARY * 0.95

    # If yesterday there was a very high bid ( > 1.2* salary ), adjust upward
    if highest_prev_bid > DAILY_SALARY * 1.2:
        # Aggressive opponent, but we have HP buffer: undercut slightly
        if hp > 5:
            base_bid = min(base_bid, highest_prev_bid - 5)
        else:
            base_bid = min(base_bid + DAILY_SALARY * 0.2, highest_prev_bid - 2)

    # Ensure not exceeding budget
    final_bid = min(budget, max(1, base_bid))
    # Round to 2 decimals
    return round(final_bid, 2)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return float(min(my_status['budget'], 10.0))

    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    if my_status['hp'] <= 3:
        return float(min(my_status['budget'], DAILY_SALARY * 1.2))

    if supply < 18:
        return float(min(my_status['budget'], DAILY_SALARY * 1.05))

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        if max_prev > DAILY_SALARY:
            return float(min(my_status['budget'], DAILY_SALARY * 0.7))

    return float(min(my_status['budget'], DAILY_SALARY * 0.85))
